#define ROOM_GYM 0
#define DECOR_NONE 0xFF

struct GymDecorPlacement
{
    u8 id;
    u8 x;
    u8 y;
    u8 room;
};

struct GymDecorSave
{
    u8 owned[GYM_DECOR_MAX_TYPES];      // how many of each the player owns (placed or stored)
    u16 numPlaced;
    u16 magic;                          // GYM_DECOR_SAVE_MAGIC once set up (older saves had other data here)
    struct GymDecorPlacement placed[GYM_DECOR_MAX_PLACED];
};

STATIC_ASSERT(sizeof(struct GymDecorSave) <= sizeof(((struct SaveBlock1 *)0)->secretBases), GymDecorSaveFitsInSecretBases);
STATIC_ASSERT(GYM_DECOR_COUNT <= GYM_DECOR_MAX_TYPES, GymDecorCatalogFitsSave);

extern const u8 GymDecor_EventScript_EditDone[];
extern const u8 GymDecor_EventScript_EditDoneReturnToPC[];

