bool32 GymDecor_IsTypeUnlocked(u32 type)
{
    const struct GymDecorTypeUnlock *unlock;
    u32 i;
    if (type >= NUMBER_OF_MON_TYPES)
        return FALSE;
    if (FlagGet(FLAG_PALLET_GYM_AWARDED))
        return TRUE;
    unlock = &sTypeUnlocks[type];
    if (unlock->flag != 0 && FlagGet(unlock->flag))
        return TRUE;
    for (i = 0; i < ARRAY_COUNT(unlock->trainers); i++)
    {
        if (unlock->trainers[i] != 0 && HasTrainerBeenFought(unlock->trainers[i]))
            return TRUE;
    }
    return FALSE;
}

bool32 GymDecor_IsUnlocked(u32 id)
{
    u32 category = gGymDecor[id].category;
    if (category >= GYM_DECOR_CAT_TYPE(0) && !GymDecor_IsTypeUnlocked(category - GYM_DECOR_CAT_TYPE(0)))
        return FALSE;
    return gGymDecor[id].unlockFlag == 0 || FlagGet(gGymDecor[id].unlockFlag);
}

// ---------------------------------------------------------------------------
// The decorations drawn in code have no room in the gym's tileset: their tiles go in video memory
// the gym doesn't use (see tools/gym_hack/build_gym_decor.py), copied there whenever the gym's
// tileset is loaded (called by src/fieldmap.c)
// ---------------------------------------------------------------------------
extern const struct Tileset gTileset_PalletGym;

void GymDecor_PatchTilesetGfx(struct MapLayout const *mapLayout)
{
    u32 i, offset = 0;
    if (mapLayout == NULL || mapLayout->secondaryTileset != &gTileset_PalletGym)
        return;
    for (i = 0; i < ARRAY_COUNT(sGymDecorArtRuns); i++)
    {
        LoadBgTiles(2, &sGymDecorArtTiles[offset * (TILE_SIZE_4BPP / 4)], sGymDecorArtRuns[i][1] * TILE_SIZE_4BPP, sGymDecorArtRuns[i][0]);
        offset += sGymDecorArtRuns[i][1];
    }
}

u32 GymDecor_CountOwned(u32 id)
{
    // The battle stage is free and always in storage (one of it)
    if (id == GYM_DECOR_BATTLE_STAGE)
        return 1;
    return GetSave()->owned[id];
}

// Where decoration `id` is placed (its top-left block), if it is
bool32 GymDecor_FindPlaced(u32 id, s32 *x, s32 *y)
{
    struct GymDecorSave *save = GetSave();
    u32 i;
    for (i = 0; i < save->numPlaced; i++)
    {
        if (save->placed[i].id == id)
        {
            *x = save->placed[i].x;
            *y = save->placed[i].y;
            return TRUE;
        }
    }
    return FALSE;
}

u32 GymDecor_CountPlaced(u32 id)
{
    struct GymDecorSave *save = GetSave();
    u32 i, n = 0;
    for (i = 0; i < save->numPlaced; i++)
    {
        if (save->placed[i].id == id)
            n++;
    }
    return n;
}

u32 GymDecor_CountAvailable(u32 id)
{
    u32 owned = GymDecor_CountOwned(id), placed = GymDecor_CountPlaced(id);
    return owned > placed ? owned - placed : 0;
}

u32 GymDecor_NumPlaced(void)
{
    return GetSave()->numPlaced;
}

// The secret base space left after the decorations (used by src/gym_challenge.c)
void *GymDecor_GetSpareSaveSpace(u32 *size)
{
    *size = sizeof(((struct SaveBlock1 *)0)->secretBases) - sizeof(struct GymDecorSave);
    return (u8 *)gSaveBlock1Ptr->secretBases + sizeof(struct GymDecorSave);
}

void GymDecor_ClearAll(void)
{
    struct GymDecorSave *save = GetSave();
    memset(save, 0, sizeof(*save));
    save->magic = GYM_DECOR_SAVE_MAGIC;
}

// The placement covering (x, y), or -1
static s32 FindPlacementAt(s32 x, s32 y)
{
    struct GymDecorSave *save = GetSave();
    s32 i;
    for (i = save->numPlaced - 1; i >= 0; i--)
    {
        const struct GymDecorPlacement *p = &save->placed[i];
        const struct GymDecor *d = &gGymDecor[p->id];
        if (p->room == ROOM_GYM && x >= p->x && x < p->x + d->width && y >= p->y && y < p->y + d->height)
            return i;
    }
    return -1;
}

static bool32 InEditArea(s32 x, s32 y)
{
    if (x < GYM_EDIT_X0 || x > GYM_EDIT_X1 || y < GYM_EDIT_Y0 || y > GYM_EDIT_Y1)
        return FALSE;
    if (x >= GYM_RESERVED_X0 && x <= GYM_RESERVED_X1 && y >= GYM_RESERVED_Y0 && y <= GYM_RESERVED_Y1)
        return FALSE;
    return TRUE;
}

bool32 GymDecor_CanPlace(u32 id, s32 x, s32 y)
{
    const struct GymDecor *d = &gGymDecor[id];
    s32 cx, cy;
    if (GymDecor_CountAvailable(id) == 0 || GetSave()->numPlaced >= GYM_DECOR_MAX_PLACED)
        return FALSE;
    if (gGymDecor[id].category == GYM_DECOR_CAT_TRAINERS && GymDecor_CountPlacedTrainers() >= GYM_PRACTICE_SLOTS)
        return FALSE;
    for (cy = y; cy < y + d->height; cy++)
    {
        for (cx = x; cx < x + d->width; cx++)
        {
            if (!InEditArea(cx, cy) || FindPlacementAt(cx, cy) >= 0)
                return FALSE;
        }
    }
    return TRUE;
}

bool32 GymDecor_Place(u32 id, s32 x, s32 y)
{
    struct GymDecorSave *save = GetSave();
    struct GymDecorPlacement *p;
    if (!GymDecor_CanPlace(id, x, y))
        return FALSE;
    p = &save->placed[save->numPlaced++];
    p->id = id;
    p->x = x;
    p->y = y;
    p->room = ROOM_GYM;
    return TRUE;
}

bool32 GymDecor_RemoveAt(s32 x, s32 y)
{
    struct GymDecorSave *save = GetSave();
    s32 i = FindPlacementAt(x, y);
    if (i < 0)
        return FALSE;
    memmove(&save->placed[i], &save->placed[i + 1], (save->numPlaced - i - 1) * sizeof(save->placed[0]));
    save->numPlaced--;
    return TRUE;
}

// ---------------------------------------------------------------------------
// Drawing
// ---------------------------------------------------------------------------
static void DrawBlock(s32 x, s32 y, u16 block, u16 editBlock, bool32 editing)
{
    u16 metatile = (editing ? editBlock : block) & MAPGRID_METATILE_ID_MASK;
    u16 collision = (block & GYM_DECOR_SOLID) ? 1 : 0;
    u16 elevation = (block & GYM_DECOR_WATER) ? 1 : 3;
    if (x < 0 || y < 0 || x >= GYM_ROOM_WIDTH || y >= GYM_ROOM_HEIGHT)
        return;
    MapGridSetMetatileEntryAt(x + MAP_OFFSET, y + MAP_OFFSET,
        metatile | (collision << MAPGRID_COLLISION_SHIFT) | (elevation << MAPGRID_ELEVATION_SHIFT));
}

static void DrawDecor(u32 id, s32 x, s32 y, bool32 editing)
{
    const struct GymDecor *d = &gGymDecor[id];
    s32 cx, cy, k = 0;
    for (cy = 0; cy < d->height; cy++)
    {
        for (cx = 0; cx < d->width; cx++, k++)
        {
            u16 edit = d->editBlocks ? d->editBlocks[k] : d->blocks[k];
            DrawBlock(x + cx, y + cy, d->blocks[k], edit, editing);
        }
    }
}

static void RestoreOriginal(s32 x, s32 y)
{
    const struct MapLayout *layout = gMapHeader.mapLayout;
    if (x < 0 || y < 0 || x >= layout->width || y >= layout->height)
        return;
    MapGridSetMetatileEntryAt(x + MAP_OFFSET, y + MAP_OFFSET, layout->map[x + y * layout->width]);
}

// Puts a rectangle of the room back the way the save says it is, and redraws it on screen
static void RefreshRect(s32 x0, s32 y0, s32 w, s32 h)
{
    struct GymDecorSave *save = GetSave();
    s32 x, y, i;
    for (y = y0; y < y0 + h; y++)
        for (x = x0; x < x0 + w; x++)
            RestoreOriginal(x, y);
    for (i = 0; i < save->numPlaced; i++)
    {
        const struct GymDecorPlacement *p = &save->placed[i];
        const struct GymDecor *d = &gGymDecor[p->id];
        if (p->room == ROOM_GYM && p->x < x0 + w && p->x + d->width > x0 && p->y < y0 + h && p->y + d->height > y0)
            DrawDecor(p->id, p->x, p->y, sEditing);
    }
    for (y = y0; y < y0 + h; y++)
        for (x = x0; x < x0 + w; x++)
            CurrentMapDrawMetatileAt(x + MAP_OFFSET, y + MAP_OFFSET);
}

// Map script (ON_LOAD): draws everything the player has placed
void GymDecor_DrawRoom(void)
{
    struct GymDecorSave *save = GetSave();
    u32 i;
    sEditing = FALSE;
    sHudWindowId = WINDOW_NONE;
    if (save->numPlaced > GYM_DECOR_MAX_PLACED)
        save->numPlaced = 0;
    for (i = 0; i < save->numPlaced; i++)
    {
        const struct GymDecorPlacement *p = &save->placed[i];
        if (p->room == ROOM_GYM && p->id < GYM_DECOR_COUNT)
            DrawDecor(p->id, p->x, p->y, FALSE);
    }
}

