static void PushItem(u32 id)
{
    struct ListMenuItem item;
    u8 *name = Alloc(32);
    StringCopy(name, gGymDecor[id].name);
    item.name = name;
    item.id = id;
    MultichoiceDynamic_PushElement(item);
}

