static bool32 InShop(u32 id)
{
    return GymDecor_IsUnlocked(id) && gGymDecor[id].price != 0;   // free ones aren't sold
}

static bool32 InStorage(u32 id)
{
    return GymDecor_CountOwned(id) > 0;
}

// Pushes the categories that have something in them (VAR_RESULT = how many)
static void PushCategories(bool32 (*has)(u32 id))
{
    u32 cat, i, n = 0;
    for (cat = 0; cat < GYM_DECOR_CAT_COUNT; cat++)
    {
        if (sCategoryNames[cat] == NULL)
            continue;
        for (i = 0; i < GYM_DECOR_COUNT; i++)
        {
            if (gGymDecor[i].category == cat && has(i))
            {
                struct ListMenuItem item;
                u8 *name = Alloc(16);
                StringCopy(name, sCategoryNames[cat]);
                item.name = name;
                item.id = cat;
                MultichoiceDynamic_PushElement(item);
                n++;
                break;
            }
        }
    }
    gSpecialVar_Result = n;
}

void GymDecor_PushShopCategories(void)
{
    PushCategories(InShop);
}

void GymDecor_PushOwnedCategories(void)
{
    PushCategories(InStorage);
}

// VAR_0x8006 = the category
void GymDecor_PushShopList(void)
{
    u32 i, n = 0;
    for (i = 0; i < GYM_DECOR_COUNT; i++)
    {
        if (gGymDecor[i].category == gSpecialVar_0x8006 && InShop(i))
        {
            PushItem(i);
            n++;
        }
    }
    gSpecialVar_Result = n;
}

// VAR_0x8006 = the category
void GymDecor_PushOwnedList(void)
{
    u32 i, n = 0;
    for (i = 0; i < GYM_DECOR_COUNT; i++)
    {
        if (gGymDecor[i].category == gSpecialVar_0x8006 && InStorage(i))
        {
            PushItem(i);
            n++;
        }
    }
    gSpecialVar_Result = n;
}

// VAR_0x8004 = decoration -> STR_VAR_1 = its name, STR_VAR_2 = its price
void GymDecor_BufferDecorInfo(void)
{
    u32 id = gSpecialVar_0x8004;
    if (id >= GYM_DECOR_COUNT)
        return;
    StringCopy(gStringVar1, gGymDecor[id].name);
    ConvertIntToDecimalStringN(gStringVar2, gGymDecor[id].price, STR_CONV_MODE_LEFT_ALIGN, 6);
}

// VAR_0x8004 = decoration. VAR_RESULT: 0 bought, 1 not enough money, 2 storage full
void GymDecor_TryBuy(void)
{
    u32 id = gSpecialVar_0x8004;
    struct GymDecorSave *save = GetSave();
    if (id >= GYM_DECOR_COUNT || save->owned[id] == 0xFF || gGymDecor[id].price == 0)
    {
        gSpecialVar_Result = 2;
        return;
    }
    if (!IsEnoughMoney(&gSaveBlock1Ptr->money, gGymDecor[id].price))
    {
        gSpecialVar_Result = 1;
        return;
    }
    RemoveMoney(&gSaveBlock1Ptr->money, gGymDecor[id].price);
    save->owned[id]++;
    gSpecialVar_Result = 0;
}

// A small window next to the list: price, how many you have, and a description
void GymDecor_ListOnInit(struct DynamicListMenuEventArgs *eventArgs)
{
    // Its tiles go right after the list's (the list is at most 5 rows tall)
    const struct WindowTemplate *list = &gWindows[eventArgs->windowId].window;
    struct WindowTemplate template = CreateWindowTemplate(0, 1, 5, 11, 8, 15, list->baseBlock + list->width * list->height);
    sListAuxWindowId = AddWindow(&template);
    SetStandardWindowBorderStyle(sListAuxWindowId, FALSE);
    FillWindowPixelBuffer(sListAuxWindowId, PIXEL_FILL(1));
    PutWindowTilemap(sListAuxWindowId);
    CopyWindowToVram(sListAuxWindowId, COPYWIN_FULL);
}

// Word-wraps a description to fit the window, breaking lines at spaces
static void WrapLine(u8 *str, u32 maxWidth, u32 fontId)
{
    u8 *lineStart = str;
    u8 *lastSpace = NULL;
    u8 *p;
    for (p = str; ; p++)
    {
        if (*p == CHAR_SPACE || *p == EOS)
        {
            u8 saved = *p;
            *p = EOS;
            if (GetStringWidth(fontId, lineStart, 0) > maxWidth && lastSpace != NULL)
            {
                *lastSpace = CHAR_NEWLINE;
                lineStart = lastSpace + 1;
            }
            *p = saved;
            if (saved == EOS)
                break;
            lastSpace = p;
        }
        else if (*p == CHAR_NEWLINE)
        {
            lineStart = p + 1;
            lastSpace = NULL;
        }
    }
}

static void PrintListInfo(u32 id, bool32 shop)
{
    u8 *str;
    u8 *line;
    if (sListAuxWindowId == WINDOW_NONE || id >= GYM_DECOR_COUNT)
        return;
    str = Alloc(160);
    FillWindowPixelBuffer(sListAuxWindowId, PIXEL_FILL(1));
    if (shop)
    {
        ConvertIntToDecimalStringN(gStringVar1, gGymDecor[id].price, STR_CONV_MODE_LEFT_ALIGN, 6);
        StringExpandPlaceholders(str, gText_PokedollarVar1);
        AddTextPrinterParameterized(sListAuxWindowId, FONT_NORMAL, str, 2, 1, TEXT_SKIP_DRAW, NULL);
        line = StringCopy(str, COMPOUND_STRING("HAVE: "));
        ConvertIntToDecimalStringN(line, GymDecor_CountOwned(id), STR_CONV_MODE_LEFT_ALIGN, 3);
    }
    else
    {
        line = StringCopy(str, COMPOUND_STRING("IN STORAGE: "));
        ConvertIntToDecimalStringN(line, GymDecor_CountAvailable(id), STR_CONV_MODE_LEFT_ALIGN, 3);
        AddTextPrinterParameterized(sListAuxWindowId, FONT_NORMAL, str, 2, 1, TEXT_SKIP_DRAW, NULL);
        line = StringCopy(str, COMPOUND_STRING("PLACED: "));
        ConvertIntToDecimalStringN(line, GymDecor_CountPlaced(id), STR_CONV_MODE_LEFT_ALIGN, 3);
    }
    AddTextPrinterParameterized(sListAuxWindowId, FONT_NORMAL, str, 2, 15, TEXT_SKIP_DRAW, NULL);
    StringCopy(str, gGymDecor[id].description);
    WrapLine(str, 11 * 8 - 4, FONT_SMALL);
    AddTextPrinterParameterized(sListAuxWindowId, FONT_SMALL, str, 2, 31, TEXT_SKIP_DRAW, NULL);
    CopyWindowToVram(sListAuxWindowId, COPYWIN_GFX);
    Free(str);
}

void GymDecor_ShopListOnSelectionChanged(struct DynamicListMenuEventArgs *eventArgs)
{
    PrintListInfo(eventArgs->selectedItem, TRUE);
}

void GymDecor_OwnedListOnSelectionChanged(struct DynamicListMenuEventArgs *eventArgs)
{
    PrintListInfo(eventArgs->selectedItem, FALSE);
}

void GymDecor_ListOnDestroy(struct DynamicListMenuEventArgs *eventArgs)
{
    if (sListAuxWindowId != WINDOW_NONE)
    {
        ClearStdWindowAndFrameToTransparent(sListAuxWindowId, TRUE);
        RemoveWindow(sListAuxWindowId);
        sListAuxWindowId = WINDOW_NONE;
    }
}

// ---------------------------------------------------------------------------
// Practice trainers: a person stands on each placed trainer decoration (data/scripts/gym_practice.inc
// battles them). The gym map has GYM_PRACTICE_SLOTS people for this (the GBA shows at most 16
// people at once, and the player, aide, challenger, Oak and the rival need 5 of them), so that's
// how many can be placed at a time; any number can be bought. Slots go to placed trainers in the
// order they were placed, and each slot's look comes from VAR_OBJ_GFX_ID_1 onward.
// ---------------------------------------------------------------------------
static const u16 sTrainerGfx[] = {OBJ_EVENT_GFX_YOUNGSTER_FRLG, OBJ_EVENT_GFX_COOLTRAINER_F, OBJ_EVENT_GFX_COOLTRAINER_M};

static bool32 IsTrainer(u32 id)
{
    return id == GYM_DECOR_TRAINER_BEGINNER || id == GYM_DECOR_TRAINER_INTERMEDIATE || id == GYM_DECOR_TRAINER_ADVANCED;
}

static u32 TrainerTier(u32 id)
{
    return id - GYM_DECOR_TRAINER_BEGINNER;
}

u32 GymDecor_CountPlacedTrainers(void)
{
    struct GymDecorSave *save = GetSave();
    u32 i, n = 0;
    for (i = 0; i < save->numPlaced; i++)
    {
        if (IsTrainer(save->placed[i].id))
            n++;
    }
    return n;
}

// The trainer in a slot: FALSE if the slot is empty. *instance counts trainers of the same rank
// placed before it (so each one gets their own name).
bool32 GymDecor_GetTrainerSlot(u32 slot, u32 *tier, u32 *instance, s32 *x, s32 *y)
{
    struct GymDecorSave *save = GetSave();
    u32 i, n = 0, sameTier[3] = {0};
    for (i = 0; i < save->numPlaced; i++)
    {
        const struct GymDecorPlacement *p = &save->placed[i];
        if (!IsTrainer(p->id))
            continue;
        if (n == slot)
        {
            *tier = TrainerTier(p->id);
            *instance = sameTier[*tier];
            *x = p->x;
            *y = p->y;
            return TRUE;
        }
        sameTier[TrainerTier(p->id)]++;
        n++;
    }
    return FALSE;
}

static u8 SlotLocalId(u32 slot)
{
    return LOCALID_PALLET_GYM_TRAINER_0 + slot;
}

// Map script (ON_TRANSITION): puts each placed trainer on their spot, hides the empty slots
void GymDecor_SetupTrainers(void)
{
    u32 slot, tier, instance;
    s32 x, y;
    for (slot = 0; slot < GYM_PRACTICE_SLOTS; slot++)
    {
        if (GymDecor_GetTrainerSlot(slot, &tier, &instance, &x, &y))
        {
            VarSet(VAR_OBJ_GFX_ID_1 + slot, sTrainerGfx[tier]);
            SetObjEventTemplateCoords(SlotLocalId(slot), x, y);
            FlagClear(FLAG_HIDE_PALLET_GYM_TRAINER_0 + slot);
        }
        else
        {
            FlagSet(FLAG_HIDE_PALLET_GYM_TRAINER_0 + slot);
        }
    }
}

// While decorating, the trainers step out of the way (their spots show an icon instead)
static void HideTrainers(void)
{
    u32 slot;
    u8 objectEventId;
    for (slot = 0; slot < GYM_PRACTICE_SLOTS; slot++)
    {
        if (!TryGetObjectEventIdByLocalIdAndMap(SlotLocalId(slot), gSaveBlock1Ptr->location.mapNum,
                                                gSaveBlock1Ptr->location.mapGroup, &objectEventId))
            gObjectEvents[objectEventId].invisible = TRUE;
    }
}

// After decorating: everyone comes back on their (new) spots, dressed for their rank
static void PlaceTrainers(void)
{
    u32 slot;
    u8 mapNum = gSaveBlock1Ptr->location.mapNum, mapGroup = gSaveBlock1Ptr->location.mapGroup;
    for (slot = 0; slot < GYM_PRACTICE_SLOTS; slot++)
        RemoveObjectEventByLocalIdAndMap(SlotLocalId(slot), mapNum, mapGroup);
    GymDecor_SetupTrainers();
    for (slot = 0; slot < GYM_PRACTICE_SLOTS; slot++)
    {
        if (!FlagGet(FLAG_HIDE_PALLET_GYM_TRAINER_0 + slot))
            TrySpawnObjectEvent(SlotLocalId(slot), mapNum, mapGroup);
    }
}

// ---------------------------------------------------------------------------
// Edit mode
// ---------------------------------------------------------------------------
bool32 GymDecor_IsEditing(void)
{
    return sEditing && InGym();
}

static void PrintHud(void)
{
    u8 *str;
    u8 *end;
    if (sHudWindowId == WINDOW_NONE)
        return;
    str = Alloc(100);
    FillWindowPixelBuffer(sHudWindowId, PIXEL_FILL(1));
    if (sSelected != DECOR_NONE)
    {
        end = StringCopy(str, gGymDecor[sSelected].name);
        if (gGymDecor[sSelected].category == GYM_DECOR_CAT_TRAINERS && GymDecor_CountPlacedTrainers() >= GYM_PRACTICE_SLOTS)
        {
            StringCopy(end, COMPOUND_STRING("  (11 TRAINERS max)"));
        }
        else
        {
            end = StringCopy(end, COMPOUND_STRING("  LEFT: "));
            ConvertIntToDecimalStringN(end, GymDecor_CountAvailable(sSelected), STR_CONV_MODE_LEFT_ALIGN, 3);
        }
    }
    else
    {
        StringCopy(str, COMPOUND_STRING("Nothing left to place"));
    }
    AddTextPrinterParameterized(sHudWindowId, FONT_NORMAL, str, 2, 1, TEXT_SKIP_DRAW, NULL);
    AddTextPrinterParameterized(sHudWindowId, FONT_SMALL,
        COMPOUND_STRING("A:place  SELECT:put away  L/R:switch  B:done"), 2, 16, TEXT_SKIP_DRAW, NULL);
    CopyWindowToVram(sHudWindowId, COPYWIN_FULL);
    Free(str);
}

static void OpenHud(void)
{
    struct WindowTemplate template = CreateWindowTemplate(0, 1, 15, 28, 4, 15, 100);
    sHudWindowId = AddWindow(&template);
    SetStandardWindowBorderStyle(sHudWindowId, FALSE);
    PutWindowTilemap(sHudWindowId);
    PrintHud();
}

static void CloseHud(void)
{
    if (sHudWindowId != WINDOW_NONE)
    {
        ClearStdWindowAndFrameToTransparent(sHudWindowId, TRUE);
        RemoveWindow(sHudWindowId);
        sHudWindowId = WINDOW_NONE;
    }
}

// Where the selected decoration would go: in front of the player, on the side facing them
static void GetTargetRect(s32 *x, s32 *y, u32 id)
{
    s16 fx, fy;
    u32 w = gGymDecor[id].width, h = gGymDecor[id].height;
    GetXYCoordsOneStepInFrontOfPlayer(&fx, &fy);
    fx -= MAP_OFFSET;
    fy -= MAP_OFFSET;
    switch (GetPlayerFacingDirection())
    {
    case DIR_NORTH:
        *x = fx - (w - 1) / 2;
        *y = fy - (h - 1);
        break;
    case DIR_SOUTH:
        *x = fx - (w - 1) / 2;
        *y = fy;
        break;
    case DIR_WEST:
        *x = fx - (w - 1);
        *y = fy - (h - 1);
        break;
    default:
        *x = fx;
        *y = fy - (h - 1);
        break;
    }
}

static void ClearPreview(void)
{
    if (sPreviewId != DECOR_NONE)
    {
        sPreviewId = DECOR_NONE;
        RefreshRect(sPreviewX, sPreviewY, sPreviewW, sPreviewH);
    }
}

static void UpdatePreview(bool32 force)
{
    s32 x, y, cx, cy;
    if (sSelected == DECOR_NONE)
    {
        ClearPreview();
        return;
    }
    GetTargetRect(&x, &y, sSelected);
    if (!force && sPreviewId == sSelected && sPreviewX == x && sPreviewY == y)
        return;
    ClearPreview();
    sPreviewId = sSelected;
    sPreviewX = x;
    sPreviewY = y;
    sPreviewW = gGymDecor[sSelected].width;
    sPreviewH = gGymDecor[sSelected].height;
    // Only draw where it could actually go, so the preview never hides what's there
    DrawDecor(sSelected, x, y, TRUE);
    for (cy = y; cy < y + sPreviewH; cy++)
    {
        for (cx = x; cx < x + sPreviewW; cx++)
        {
            if (!InEditArea(cx, cy) || FindPlacementAt(cx, cy) >= 0)
                RefreshRect(cx, cy, 1, 1);
            else
                CurrentMapDrawMetatileAt(cx + MAP_OFFSET, cy + MAP_OFFSET);
        }
    }
}

static void SelectNext(s32 step)
{
    u32 i, id = (sSelected == DECOR_NONE) ? 0 : sSelected;
    for (i = 0; i < GYM_DECOR_COUNT; i++)
    {
        id = (id + GYM_DECOR_COUNT + step) % GYM_DECOR_COUNT;
        if (GymDecor_CountAvailable(id) > 0)
        {
            sSelected = id;
            return;
        }
    }
    sSelected = DECOR_NONE;
}

// Special: VAR_0x8004 = the decoration to start with
void GymDecor_StartEditing(void)
{
    sEditing = TRUE;
    sSelected = gSpecialVar_0x8004 < GYM_DECOR_COUNT ? gSpecialVar_0x8004 : DECOR_NONE;
    if (sSelected != DECOR_NONE && GymDecor_CountAvailable(sSelected) == 0)
        SelectNext(1);
    sPreviewId = DECOR_NONE;
    RefreshRect(0, 0, GYM_ROOM_WIDTH, GYM_ROOM_HEIGHT);   // shows invisible walls
    HideTrainers();
    OpenHud();
    UpdatePreview(TRUE);
}

// Can the player walk from where they stand back to the PC?
static bool32 CanReachPC(void)
{
    u8 *seen = AllocZeroed(GYM_ROOM_WIDTH * GYM_ROOM_HEIGHT);
    s16 *queue = Alloc(GYM_ROOM_WIDTH * GYM_ROOM_HEIGHT * sizeof(s16));
    s32 head = 0, tail = 0;
    s16 px, py;
    bool32 found = FALSE;
    static const s8 dx[] = {1, -1, 0, 0}, dy[] = {0, 0, 1, -1};

    PlayerGetDestCoords(&px, &py);
    px -= MAP_OFFSET;
    py -= MAP_OFFSET;
    if (px < 0 || py < 0 || px >= GYM_ROOM_WIDTH || py >= GYM_ROOM_HEIGHT
     || MapGridGetCollisionAt(px + MAP_OFFSET, py + MAP_OFFSET)
     || MapGridGetElevationAt(px + MAP_OFFSET, py + MAP_OFFSET) != 3)
        goto done;
    queue[tail++] = px + py * GYM_ROOM_WIDTH;
    seen[px + py * GYM_ROOM_WIDTH] = TRUE;
    while (head < tail)
    {
        s32 cur = queue[head++], x = cur % GYM_ROOM_WIDTH, y = cur / GYM_ROOM_WIDTH, i;
        if (x == GYM_PC_FRONT_X && y == GYM_PC_FRONT_Y)
        {
            found = TRUE;
            break;
        }
        for (i = 0; i < 4; i++)
        {
            s32 nx = x + dx[i], ny = y + dy[i];
            if (nx < 0 || ny < 0 || nx >= GYM_ROOM_WIDTH || ny >= GYM_ROOM_HEIGHT || seen[nx + ny * GYM_ROOM_WIDTH])
                continue;
            seen[nx + ny * GYM_ROOM_WIDTH] = TRUE;
            if (MapGridGetCollisionAt(nx + MAP_OFFSET, ny + MAP_OFFSET)
             || MapGridGetElevationAt(nx + MAP_OFFSET, ny + MAP_OFFSET) != 3)
                continue;
            queue[tail++] = nx + ny * GYM_ROOM_WIDTH;
        }
    }
done:
    Free(seen);
    Free(queue);
    return found;
}

static void StopEditing(void)
{
    ClearPreview();
    CloseHud();
    sEditing = FALSE;
    RefreshRect(0, 0, GYM_ROOM_WIDTH, GYM_ROOM_HEIGHT);   // hides invisible walls again
    PlaceTrainers();
    if (CanReachPC())
        ScriptContext_SetupScript(GymDecor_EventScript_EditDone);
    else
        ScriptContext_SetupScript(GymDecor_EventScript_EditDoneReturnToPC);
}

// Called by ProcessPlayerFieldInput every frame while editing. Returns TRUE if a script started.
bool32 GymDecor_HandleEditInput(struct FieldInput *input)
{
    s32 x, y;
    s16 px, py;

    if (input->pressedBButton)
    {
        PlaySE(SE_SELECT);
        StopEditing();
        return TRUE;
    }

    // Keep the player inside the room, and off the doormat
    if (input->dpadDirection != DIR_NONE)
    {
        PlayerGetDestCoords(&px, &py);
        px -= MAP_OFFSET;
        py -= MAP_OFFSET;
        switch (input->dpadDirection)
        {
        case DIR_NORTH: py--; break;
        case DIR_SOUTH: py++; break;
        case DIR_WEST:  px--; break;
        case DIR_EAST:  px++; break;
        default: break;
        }
        if (px < 0 || px >= GYM_ROOM_WIDTH || py < GYM_EDIT_Y0 || py > GYM_ROOM_HEIGHT - 2
         || (py == GYM_ROOM_HEIGHT - 2 && px >= GYM_MAT_X0 && px <= GYM_MAT_X1))
            input->dpadDirection = DIR_NONE;
    }

    if (JOY_NEW(L_BUTTON) || JOY_NEW(R_BUTTON))
    {
        SelectNext(JOY_NEW(R_BUTTON) ? 1 : -1);
        PlaySE(SE_SELECT);
        PrintHud();
        UpdatePreview(TRUE);
    }
    else if (input->pressedAButton)
    {
        if (sSelected != DECOR_NONE)
        {
            GetTargetRect(&x, &y, sSelected);
            if (GymDecor_Place(sSelected, x, y))
            {
                PlaySE(SE_CLICK);
                sPreviewId = DECOR_NONE;          // it's real now
                RefreshRect(x, y, gGymDecor[sSelected].width, gGymDecor[sSelected].height);
                if (GymDecor_CountAvailable(sSelected) == 0)
                    SelectNext(1);
                PrintHud();
                UpdatePreview(TRUE);
            }
            else
            {
                PlaySE(SE_FAILURE);
            }
        }
        else
        {
            PlaySE(SE_FAILURE);
        }
    }
    else if (input->pressedSelectButton)
    {
        s16 fx, fy;
        GetXYCoordsOneStepInFrontOfPlayer(&fx, &fy);
        ClearPreview();
        if (GymDecor_RemoveAt(fx - MAP_OFFSET, fy - MAP_OFFSET))
        {
            PlaySE(SE_CLICK);
            RefreshRect(0, 0, GYM_ROOM_WIDTH, GYM_ROOM_HEIGHT);
            if (sSelected == DECOR_NONE)
                SelectNext(1);
            PrintHud();
        }
        else
        {
            PlaySE(SE_FAILURE);
        }
        UpdatePreview(TRUE);
    }
    else
    {
        UpdatePreview(FALSE);
    }

    input->pressedAButton = FALSE;
    input->pressedStartButton = FALSE;
    input->pressedSelectButton = FALSE;
    input->pressedRButton = FALSE;
    return FALSE;
}
